/* Local prototype archive. IndexedDB holds images and immutable capture metadata.
   All generated camera images are illustrations; no automatic camera detection. */
let vaultFailedRecords=[],vaultEvents=[],vaultReady=false,vaultError='',vaultDB=null,vaultPending=0;
let vaultFilters={search:'',status:'all',camera:'all',date:''};
let vaultSaveQueue=Promise.resolve(),vaultInitPromise;
const vaultTZ='America/Edmonton';
const vaultDate=iso=>new Intl.DateTimeFormat('en-CA',{timeZone:vaultTZ,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(iso));
const vaultTime=iso=>new Intl.DateTimeFormat('en-CA',{timeZone:vaultTZ,hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date(iso));
const vaultStamp=iso=>vaultDate(iso)+' · '+vaultTime(iso);
const normalizePlate=p=>String(p||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
function vaultTransaction(records){return new Promise((resolve,reject)=>{const tx=vaultDB.transaction('captures','readwrite');for(const record of records)tx.objectStore('captures').put(record);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Storage write cancelled'));})}
async function initVault(){
 try{
  vaultDB=await new Promise((resolve,reject)=>{const request=indexedDB.open('rc-scale-photo-vault-demo',1);request.onupgradeneeded=()=>{request.result.createObjectStore('captures',{keyPath:'id'});request.result.createObjectStore('meta',{keyPath:'id'});};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);request.onblocked=()=>reject(new Error('Close an older prototype tab and reload.'));});
  const read=store=>new Promise((resolve,reject)=>{const req=vaultDB.transaction(store).objectStore(store).getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});
  vaultEvents=await read('captures');const meta=await read('meta');
  if(!meta.some(m=>m.id==='seeded')){
   const initial=seedVault();await new Promise((resolve,reject)=>{const tx=vaultDB.transaction(['captures','meta'],'readwrite');initial.forEach(e=>tx.objectStore('captures').put(e));tx.objectStore('meta').put({id:'seeded',at:new Date().toISOString()});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});vaultEvents=initial;
  }
  const repaired=vaultEvents.filter(e=>e.ticketId===160&&e.direction==='out'&&e.basis==='Sample ticket capture · explicit ticket ID'&&e.occurredAt==='2026-10-16T08:15:34-06:00');repaired.forEach(e=>e.occurredAt='2026-10-16T08:52:34-06:00');if(repaired.length)await vaultTransaction(repaired);
  vaultReady=true;renderEquipment();if(page==='vault')renderVault();
 }catch(err){vaultError='Photo storage is unavailable. '+(err.message||'Allow local browser storage and reload.');vaultReady=true;if(page==='vault')renderVault();}
}
function vaultImage(c,direction){
 const pt=c.ptz||{x:0,y:0,z:1};const moved=cameraArt.replace(/(<svg[^>]*>)/,'$1<g transform="translate('+(pt.x*6)+' '+(pt.y*3)+') translate(300 150) scale('+pt.z+') translate(-300 -150)">').replace('</svg>','</g></svg>');
 const svg=moved.replace('viewBox="0 0 600 300"','viewBox="0 0 600 300"').replace('</svg>','<rect x="0" y="263" width="600" height="37" fill="#16372c"/><text x="15" y="287" fill="white" font-family="sans-serif" font-size="12">'+esc(c.name)+' · '+esc(direction.toUpperCase())+' · ILLUSTRATED DEMO CAPTURE</text></svg>');
 return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);
}
function vaultRecord(c,direction,extra={}){return {id:crypto.randomUUID(),visit:crypto.randomUUID(),direction,occurredAt:new Date().toISOString(),recordedAt:new Date().toISOString(),timezone:vaultTZ,cameraId:c?.id||'upload',cameraName:c?.name||'Material attachment',source:c?.source||'Uploaded picture',image:c?vaultImage(c,direction):'',captureStatus:'saved',ticketId:null,ticketNumber:'',plate:'',customer:'',driver:'',vehicle:'',colour:'',material:'',weight:null,gross:null,tare:null,net:null,notes:'',operator:'EG · demo operator',station:'Station 01',basis:'Operator capture',demo:true,...extra}}
function appendVault(records){
 vaultPending+=records.length;
 vaultSaveQueue=vaultSaveQueue.then(async()=>{
  await vaultInitPromise;
  if(!vaultReady||!vaultDB)throw new Error('Photo Vault is not ready. Reload and retry.');
  await vaultTransaction(records);vaultError='';vaultEvents.push(...records.filter(r=>!vaultEvents.some(e=>e.id===r.id)));vaultFailedRecords=vaultFailedRecords.filter(e=>!records.some(r=>r.id===e.id));renderEquipment();
 }).catch(err=>{vaultFailedRecords.push(...records.filter(r=>!vaultFailedRecords.some(e=>e.id===r.id)));vaultError='Capture could not be saved: '+(err.message||'Storage is full.');toast(vaultError);}).finally(()=>{vaultPending-=records.length;if(page==='vault')renderVault()});
 if(page==='vault')renderVault();return vaultSaveQueue;
}
function ticketVisit(t){return t.vaultVisit||('seed-ticket-'+t.id)}
function captureTicketVault(t,direction){
 ensureCameras();const cameras=state.cameras.filter(c=>c.enabled);
 const info={visit:ticketVisit(t),ticketId:t.id,ticketNumber:ticketNumber(t),plate:t.plate||'',customer:t.customer||'',driver:t.driver||'',vehicle:t.vehicle||'',colour:t.colour||'',material:t.material,notes:t.notes||'',weight:direction==='in'?t.gross:t.tare,gross:t.gross,tare:t.tare||null,net:direction==='out'?net(t):null,basis:'Ticket '+(direction==='in'?'weigh-in':'weigh-out')+' · explicit ticket ID'};
 const records=cameras.map(c=>vaultRecord(c,direction,{...info,photoRole:c.id===state.photoCamera?'Ticket photo':'Supporting angle'}));
 if(!records.length)records.push(vaultRecord(null,direction,{...info,cameraId:'none',cameraName:'No enabled camera',image:'',captureStatus:'missing',basis:'Capture missed · all cameras paused'}));
 appendVault(records);
}
function captureManualVault(c){appendVault([vaultRecord(c,'snapshot',{weight:state.connected?state.weight:null,basis:'Manual snapshot',notes:'Illustrated capture; movement preview is not physical PTZ.',ptz:{...(c.ptz||{x:0,y:0,z:1})}})])}
function captureMaterialVault(name,notes,picture){appendVault([vaultRecord(null,'material',{material:name,notes,image:picture,basis:'Material reference upload'})])}
function seedVault(){
 ensureCameras();const c=state.cameras[0],events=[];
 for(const id of [159,160]){const t=getTicket(id);if(!t)continue;const common={visit:'seed-ticket-'+id,ticketId:id,ticketNumber:ticketNumber(t),plate:t.plate,customer:t.customer,driver:t.driver,material:t.material,gross:t.gross,tare:t.tare||null,net:t.tare?t.gross-t.tare:null,basis:'Sample ticket capture · explicit ticket ID'};
 events.push(vaultRecord(c,'in',{...common,occurredAt:'2026-10-16T'+(id===159?'07:51:12':'08:32:09')+'-06:00',weight:t.gross}));
 if(t.status==='completed')events.push(vaultRecord(c,'out',{...common,occurredAt:'2026-10-16T'+(id===160?'08:52:34':'08:15:34')+'-06:00',weight:t.tare}));}
 events.push(vaultRecord(state.cameras[1]||c,'out',{plate:'DEMO 704',occurredAt:'2026-10-16T08:41:22-06:00',basis:'Sample departure · no arrival match',notes:'No matching arrival captured. Review this visit.'}));
 events.push(vaultRecord(c,'snapshot',{occurredAt:'2026-10-16T08:45:16-06:00',notes:'Sample manual yard check.'}));return events;
}
function vaultGroups(){
 const map=new Map();for(const e of vaultEvents){if(!map.has(e.visit))map.set(e.visit,[]);map.get(e.visit).push(e)}
 return [...map].map(([id,events])=>{events.sort((a,b)=>new Date(a.occurredAt)-new Date(b.occurredAt));const incoming=events.filter(e=>e.direction==='in'),outgoing=events.filter(e=>e.direction==='out');const status=incoming.length&&outgoing.length?'paired':incoming.length?'in':outgoing.length?'out':'other';return {id,events,incoming,outgoing,status,first:events[0],latest:events[events.length-1],photos:events.filter(e=>e.image).length}}).sort((a,b)=>new Date(b.latest.occurredAt)-new Date(a.latest.occurredAt));
}
const vaultStatus=g=>({paired:'Arrival & departure paired',in:'Awaiting departure',out:'Departure only · review',other:g.first.direction==='material'?'Material reference':'Manual snapshot'}[g.status]);
function visibleVaultGroups(){return vaultGroups().filter(g=>{
 const q=vaultFilters.search.toLowerCase().trim();return (!q||g.events.some(e=>[e.plate,e.ticketNumber,e.customer,e.driver,e.vehicle,e.colour,e.material,e.notes,e.cameraName].join(' ').toLowerCase().includes(q)))&&(vaultFilters.status==='all'||vaultFilters.status==='review'&&['in','out'].includes(g.status)||g.status===vaultFilters.status)&&(vaultFilters.camera==='all'||g.events.some(e=>e.cameraId===vaultFilters.camera))&&(!vaultFilters.date||g.events.some(e=>vaultDate(e.occurredAt)===vaultFilters.date));
})}
function vaultPhoto(e,label){return e?'<div class="vault-photo">'+(e.image?'<img src="'+esc(e.image)+'" alt="'+esc(label+' · '+e.cameraName)+'">':'<div class="vault-no-photo">Photo unavailable</div>')+'<div><strong>'+esc(label)+'</strong><span>'+vaultTime(e.occurredAt)+'</span></div></div>':'<div class="vault-photo vault-wait"><span>◷</span><strong>'+label+'</strong><small>No capture recorded yet</small></div>'}
function openVault(){go('vault');renderVault()}
function renderVault(){
 const root=$('vault');if(!root)return;
 if(!vaultReady){root.innerHTML='<div class="empty">Opening Photo Vault…</div>';return;}
 const groups=vaultGroups(),photos=vaultEvents.filter(e=>e.image).length,cameras=[...new Map(vaultEvents.map(e=>[e.cameraId,e.cameraName])).entries()];
 root.innerHTML='<div class="vault-top"><button class="text-button" data-page="equipment">← Equipment & settings</button><div><button class="button" data-vault="export">↓ Export records</button><button class="button primary" data-vault="simulate">＋ Simulate camera event</button></div></div><div class="callout vault-notice">Local demo archive · camera images are illustrations. Arrival/departure detection is simulated. Pictures stay in this browser; export a visit for a portable copy.</div>'+(vaultError?'<div class="vault-error" role="alert">'+esc(vaultError)+(vaultFailedRecords.length?'<button class="button" data-vault="retry">Retry '+vaultFailedRecords.length+' captures</button>':'')+'</div>':'')+(vaultPending?'<p role="status">Saving '+vaultPending+' captures…</p>':'')+'<div class="history-summary"><div class="summary-box"><span>Pictures saved</span><strong>'+photos+'</strong></div><div class="summary-box"><span>Paired visits</span><strong>'+groups.filter(g=>g.status==='paired').length+'</strong></div><div class="summary-box"><span>Arrival or departure only</span><strong>'+groups.filter(g=>g.status==='in'||g.status==='out').length+'</strong></div></div><section class="panel"><div class="vault-filters"><label class="filter-field vault-search">Find a capture<input type="search" id="vault-search" placeholder="Plate, ticket, customer, material or notes" value="'+esc(vaultFilters.search)+'"></label><label class="filter-field">Visit status<select id="vault-status">'+[['all','All captures'],['paired','Paired visits'],['in','Awaiting departure'],['out','Departure only'],['review','Unpaired visits'],['other','Snapshots & materials']].map(([v,l])=>'<option value="'+v+'" '+(v===vaultFilters.status?'selected':'')+'>'+l+'</option>').join('')+'</select></label><label class="filter-field">Camera<select id="vault-camera"><option value="all">All cameras</option>'+cameras.map(([id,name])=>'<option value="'+esc(id)+'" '+(id===vaultFilters.camera?'selected':'')+'>'+esc(name)+'</option>').join('')+'</select></label><label class="filter-field">Capture date<input type="date" id="vault-date" value="'+esc(vaultFilters.date)+'"></label><button class="text-button" data-vault="clear">Clear filters</button></div><div class="vault-results-heading"><span id="vault-result-count"></span><span>Times shown in Edmonton</span></div><div id="vault-results"></div></section>';
 renderVaultResults();
}
function renderVaultResults(){const groups=visibleVaultGroups();$('vault-result-count').textContent=groups.length+' visits / capture groups';$('vault-results').innerHTML=groups.length?groups.map(g=>'<button class="vault-row" data-vault-visit="'+g.id+'"><div class="vault-row-heading"><div><strong>'+esc(g.events.find(e=>e.plate)?.plate||g.first.material||'Unidentified capture')+'</strong><span>'+esc(g.events.find(e=>e.customer)?.customer||'Customer not linked')+'</span></div><span class="pill '+(g.status==='paired'?'good':g.status==='out'?'bad':'')+'">'+vaultStatus(g)+'</span></div><div class="vault-pair">'+(g.status==='other'?vaultPhoto(g.first,g.first.direction==='material'?'Material picture':'Snapshot'):vaultPhoto(g.incoming[0],'Arrival')+vaultPhoto(g.outgoing[0],'Departure'))+'</div><div class="vault-row-foot"><span>'+vaultDate(g.first.occurredAt)+' · '+g.photos+' pictures'+(g.first.ticketNumber?' · '+esc(g.first.ticketNumber):'')+'</span><strong>View visit →</strong></div></button>').join(''):'<div class="empty">No captures match. Clear a filter or simulate a camera event.</div>'}
function vaultVisit(id){
 const g=vaultGroups().find(g=>g.id===id);if(!g)return;const duration=g.status==='paired'?Math.round((new Date(g.outgoing[0].occurredAt)-new Date(g.incoming[0].occurredAt))/60000):null;
 modal(g.events.find(e=>e.plate)?.plate||'Capture details','<div class="vault-detail-status"><span class="pill '+(g.status==='paired'?'good':'')+'">'+vaultStatus(g)+'</span><span>'+g.photos+' saved pictures'+(duration!==null?' · '+duration+' min on site':'')+'</span></div><p class="settings-note">Capture details are preserved as recorded. All dates and times below are Edmonton time. Sample camera pictures are illustrations.</p><div class="vault-gallery">'+g.events.map(e=>'<article class="vault-event"><div class="vault-event-title"><h3>'+({in:'Arrival',out:'Departure',snapshot:'Manual snapshot',material:'Material picture'}[e.direction])+'</h3><span>'+vaultStamp(e.occurredAt)+'</span></div>'+(e.image?'<a href="'+esc(e.image)+'" download="'+e.id+(e.direction==='material'?'.jpg':'.svg')+'" title="Download this picture"><img class="vault-detail-image" src="'+esc(e.image)+'" alt="'+esc(e.cameraName+' '+e.direction)+'"></a>':'<div class="callout amber">No image was captured for this event.</div>')+'<div class="detail-list">'+[['Camera',e.cameraName],['Ticket',e.ticketNumber||'Not linked'],['Customer',e.customer||'Not recorded'],['Licence plate',e.plate||'Not recorded'],['Weight',e.weight===null?'Not recorded':fmt(e.weight)+' kg'],['Material',e.material||'Not recorded'],['Pairing evidence',e.basis]].map(([k,v])=>'<div><span>'+k+'</span><strong>'+esc(v)+'</strong></div>').join('')+'</div><details class="vault-metadata"><summary>All capture information</summary><div class="detail-list">'+[['Capture ID',e.id],['Visit ID',e.visit],['Event timestamp (ISO)',e.occurredAt],['Archived (ISO)',e.recordedAt],['Time zone',e.timezone],['Station',e.station],['Operator',e.operator],['Source',e.source],['Capture status',e.captureStatus],['Driver',e.driver||'Not recorded'],['Vehicle',e.vehicle||'Not recorded'],['Colour',e.colour||'Not recorded'],['Gross',e.gross==null?'Not recorded':fmt(e.gross)+' kg'],['Tare',e.tare==null?'Not recorded':fmt(e.tare)+' kg'],['Net',e.net==null?'Not recorded':fmt(e.net)+' kg'],['Photo role',e.photoRole||'Reference'],['Notes',e.notes||'None'],['Pairing review history',(e.pairingHistory||[]).map(h=>h.action+' · '+h.at+(h.reason?' · '+h.reason:'')).join('\n')||'No manual changes']].map(([k,v])=>'<div><span>'+k+'</span><strong>'+esc(v)+'</strong></div>').join('')+'</div></details></article>').join('')+'</div><div class="modal-actions"><button class="button" data-action="close">Close</button><button class="button" data-vault-pair="'+id+'">Link / correct pairing</button><button class="button primary" data-vault-download="'+id+'">Download visit & pictures</button></div>','PHOTO VAULT');$('modal').classList.add('camera-wide');
}
function simulateVaultEvent(){
 ensureCameras();modal('Log a camera event','<p class="modal-intro">Try an arrival or departure without creating a scale ticket. The prototype uses an illustration, not your cameras.</p><form id="vault-event-form"><div class="form-grid"><label class="field">Direction<select name="direction"><option value="in">Truck arriving</option><option value="out">Truck leaving</option></select></label><label class="field">Camera<select name="camera">'+state.cameras.filter(c=>c.enabled).map(c=>'<option value="'+c.id+'">'+esc(c.name)+'</option>').join('')+'</select></label></div><label class="field">Licence plate<input name="plate" maxlength="20" placeholder="e.g. BTR 4821"><small>Optional. Missing or ambiguous plates remain unpaired.</small></label><label class="field">Customer<input name="customer" maxlength="120" placeholder="If known"></label><label class="field">Notes<textarea name="notes" maxlength="2000" placeholder="Anything useful about the visit"></textarea></label><div class="callout">A departure pairs only when exactly one arrival in the last 12 hours has this plate. Otherwise it is kept as “Departure only” for review.</div>'+actions('<button class="button primary" type="submit" '+(!state.cameras.some(c=>c.enabled)?'disabled':'')+'>Save sample capture</button>')+'</form>','SIMULATED DETECTION');
}
function pairVault(id){const g=vaultGroups().find(g=>g.id===id);if(!g)return;const opposite=g.status==='out'?'in':g.status==='in'?'out':null;const candidates=opposite?vaultGroups().filter(x=>x.status===opposite&&x.id!==id):[];modal('Review visit pairing','<p class="modal-intro">Link photos only when you know they show the same truck visit. The original capture details stay intact.</p>'+(candidates.length?'<form id="vault-pair-form" data-visit="'+id+'"><label class="field">Match with<select name="match">'+candidates.map(x=>'<option value="'+x.id+'">'+esc(x.first.plate||'Unknown plate')+' · '+vaultStamp(x.first.occurredAt)+'</option>').join('')+'</select></label><label class="field">Reason for linking<textarea name="reason" required maxlength="1000" placeholder="How did you confirm it is the same visit?"></textarea></label>'+actions('<button class="button primary" type="submit">Link this visit</button>')+'</form>':g.status==='paired'?'<p class="callout">This visit is paired. If the pairing is wrong, split the arrival and departure for review.</p><div class="modal-actions"><button class="button" data-action="close">Cancel</button><button class="button danger" data-vault-unpair="'+id+'">Unpair visit</button></div>':'<div class="empty">No opposite-direction visit is available to link.</div>'),'MANUAL REVIEW')}
function vaultDownload(id){
 const groups=id?vaultGroups().filter(g=>g.id===id):visibleVaultGroups(),records=groups.flatMap(g=>g.events);
 if(id){
 const report='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Photo Vault visit</title><style>body{font:15px system-ui;max-width:1000px;margin:40px auto;padding:20px;background:#f5f7f1;color:#203b2c}article{background:white;border:1px solid #dbe3d2;border-radius:14px;margin:20px 0;padding:24px}img{width:100%;max-height:450px;object-fit:contain}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}p{line-height:1.7}</style><h1>Photo Vault · visit record</h1><p>Local prototype export · camera images are illustrations. Times shown in Edmonton.</p>'+records.map(e=>'<article><h2>'+esc(e.direction.toUpperCase())+' · '+esc(e.plate||'Unknown plate')+'</h2><p>'+vaultStamp(e.occurredAt)+' · '+esc(e.cameraName)+'<br>'+esc(e.customer||'Customer not recorded')+' · '+esc(e.ticketNumber||'No ticket linked')+'</p>'+(e.image?'<img src="'+esc(e.image)+'" alt="Capture">':'<p>No picture captured.</p>')+'<details><summary>All recorded information</summary><pre>'+esc(JSON.stringify({...e,image:undefined},null,2))+'</pre></details></article>').join('')+'</html>';
 download('photo-vault-visit.html',report,'text/html');toast('Visit downloaded with pictures and capture details.');
 }else{download('photo-vault-records.json',JSON.stringify({exportedAt:new Date().toISOString(),timezone:vaultTZ,demo:true,includesImages:false,records:records.map(e=>({...e,image:undefined}))},null,2),'application/json');toast('Filtered metadata exported. Download a visit to include pictures.');}
}

document.addEventListener('input',e=>{const key={'vault-search':'search','vault-status':'status','vault-camera':'camera','vault-date':'date'}[e.target.id];if(key){vaultFilters[key]=e.target.value;renderVaultResults()}});
document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.vaultVisit)return vaultVisit(b.dataset.vaultVisit);
 if(b.dataset.vaultDownload)return vaultDownload(b.dataset.vaultDownload);
 if(b.dataset.vaultPair)return pairVault(b.dataset.vaultPair);
 if(b.dataset.vaultUnpair){const g=vaultGroups().find(g=>g.id===b.dataset.vaultUnpair),newVisit=crypto.randomUUID();const updated=g.outgoing.map(e=>({...e,visit:newVisit,pairingHistory:[...(e.pairingHistory||[]),{action:'unpaired',from:e.visit,at:new Date().toISOString(),operator:'EG'}]}));try{await vaultTransaction(updated);updated.forEach(e=>vaultEvents[vaultEvents.findIndex(x=>x.id===e.id)]=e);renderVault();close();toast('Visit unpaired. Both sides remain in the archive.')}catch{toast('Could not save pairing change.')}return;}
 switch(b.dataset.vault){case'retry':appendVault([...vaultFailedRecords]);break;case'simulate':simulateVaultEvent();break;case'export':vaultDownload();break;case'clear':vaultFilters={search:'',status:'all',camera:'all',date:''};renderVault();break;}
});
document.addEventListener('submit',async e=>{
 const form=e.target;if(!['vault-event-form','vault-pair-form'].includes(form.id))return;e.preventDefault();if(form.dataset.saving)return;const d=new FormData(form);
 if(form.id==='vault-event-form'){
 const camera=state.cameras.find(c=>c.id===d.get('camera')&&c.enabled);if(!camera)return toast('Choose an enabled camera.');const direction=String(d.get('direction')),plate=String(d.get('plate')).trim().toUpperCase();
 const matches=direction==='out'&&normalizePlate(plate)?vaultGroups().filter(g=>g.status==='in'&&normalizePlate(g.first.plate)===normalizePlate(plate)&&Date.now()-new Date(g.first.occurredAt)>=0&&Date.now()-new Date(g.first.occurredAt)<=12*3600000):[];
 const match=matches.length===1?matches[0]:null;
 const record=vaultRecord(camera,direction,{plate,customer:String(d.get('customer')).trim(),notes:String(d.get('notes')).trim(),basis:match?'Exact operator-entered plate · one arrival within 12h':'Operator simulated event · no unambiguous match',...(match?{visit:match.id,ticketId:match.first.ticketId,ticketNumber:match.first.ticketNumber}:{} )});
 form.dataset.saving='true';form.querySelector('[type=submit]').disabled=true;await appendVault([record]);delete form.dataset.saving;form.querySelector('[type=submit]').disabled=false;if(vaultEvents.some(x=>x.id===record.id)){close();openVault();toast(match?'Departure paired with its arrival.':'Capture saved to Photo Vault.');}
 }else{
 const current=vaultGroups().find(g=>g.id===form.dataset.visit),target=vaultGroups().find(g=>g.id===d.get('match'));if(!current||!target||!((current.status==='in'&&target.status==='out')||(current.status==='out'&&target.status==='in')))return toast('These visits can no longer be linked.');
 const incoming=current.status==='in'?current:target,outgoing=current.status==='out'?current:target;if(new Date(outgoing.first.occurredAt)<new Date(incoming.first.occurredAt))return toast('Departure time is earlier than arrival. Choose another visit.');
 const reason=String(d.get('reason')).trim();if(!reason)return toast('Enter a reason for linking.');const updated=outgoing.events.map(x=>({...x,visit:incoming.id,pairingHistory:[...(x.pairingHistory||[]),{action:'linked',from:x.visit,to:incoming.id,reason,at:new Date().toISOString(),operator:'EG'}]}));
 try{await vaultTransaction(updated);updated.forEach(x=>vaultEvents[vaultEvents.findIndex(y=>y.id===x.id)]=x);renderVault();vaultVisit(incoming.id);toast('Visit linked. Original capture information preserved.')}catch{toast('Could not save pairing change.')}
 }
});
